def is_decimal(s):
    if not isinstance(s, str):
        return False
    # Check if the string matches pattern: optional sign, one or more digits, dot, exactly two digits
    import re
    pattern = r'^[+-]?\d+\.\d{2}$'
    return bool(re.match(pattern, s))

def is_Two_Alter(s: str) -> bool:
    # If the string length is 1, it trivially alternates (only one character)
    if len(s) == 1:
        return True
    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False
    # Check strict alternation: s[i] != s[i+1] for all i
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False
    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0
    max_current = max_global = arr[0]
    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current
    return max_global

def len_log(words):
    if not words:
        return 0
    return max(len(word) for word in words)

