def minPath(grid, k):
    from collections import deque

    N = len(grid)
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    import heapq

    # We'll use a heap and keep track of visited states to avoid revisiting same position with same path length
    # Because lex order depends on path values, we keep full path in the heap.
    # To avoid infinite expansions, track visited as (r, c, length_of_path)
    visited = set()

    heap = []
    for r in range(N):
        for c in range(N):
            val = grid[r][c]
            path = (val,)
            heapq.heappush(heap, (path, r, c))
            visited.add((r, c, 1))

    while heap:
        path_vals, r, c = heapq.heappop(heap)
        if len(path_vals) == k:
            return list(path_vals)
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                nlen = len(path_vals) + 1
                if (nr, nc, nlen) not in visited:
                    nval = grid[nr][nc]
                    new_path = path_vals + (nval,)
                    visited.add((nr, nc, nlen))
                    heapq.heappush(heap, (new_path, nr, nc))
    return []

def cycpattern_check(a, b):
    if not b:
        return True  # empty substring trivially in any string
    n = len(b)
    doubled = b + b
    for i in range(n):
        rotation = doubled[i:i+n]
        if rotation in a:
            return True
    return False

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.strip().split()
    result = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5)+1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    # Only consider words of prime length greater than 1
    prime_words = [w for w in words if is_prime(len(w))]
    # Return the first prime-length word only
    return prime_words[0] if prime_words else ''

