def even_odd_palindrome(n):
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        if is_palindrome(num):
            # Count based on parity of the number itself, not length of digits
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def correct_bracketing(brackets: str):
    count = 0
    for ch in brackets:
        if ch == "<":
            count += 1
        elif ch == ">":
            count -= 1
            if count < 0:
                return False
    return count == 0
